(async () => {
    const g = __rhf.game;
    const D = g.props.wreckDeck;
    // walk up the gangplank: place at its foot and hold forward
    const p = g.world.place('wreck');
    const w = p.wreckAt;
    const bx = w.x + Math.sin(w.yaw) * 10;
    const bz = w.z + Math.cos(w.yaw) * 10;
    __view(p.beachX, p.beachZ, bx, D.top + 1.5, bz);
    const k = g.input;
    k.keys.add('KeyW');
    const t0 = g.time;
    await __until(() => g.player.onDeck && Math.hypot(g.player.pos.x - D.x, g.player.pos.z - D.z) < 9 || g.time - t0 > 14, 200000);
    k.keys.delete('KeyW');
    const P = g.player;
    return 'after walking up: on a deck ' + P.onDeck + ', y ' + P.pos.y.toFixed(2) + ' (deck ' + D.top.toFixed(2) + '), ' + Math.hypot(P.pos.x - D.x, P.pos.z - D.z).toFixed(1) + ' m from the middle, flag ' + !!g.state.flags.deck;
  })()

(() => {
    const g = __rhf.game;
    const p = g.world.place('wreck');
    const P = g.player;
    P.yaw = Math.atan2(-(p.waterX - P.pos.x), -(p.waterZ - P.pos.z));
    P.pitch = -0.15;
    return 'looking out to sea';
  })()

(async () => {
    const g = __rhf.game;
    const p = g.world.place('wreck');
    const w = p.wreckAt;
    const c = Math.cos(w.yaw);
    const sn = Math.sin(w.yaw);
    const to = (lx, lz) => [w.x + lx * c + lz * sn, w.z - lx * sn + lz * c];
    const P = g.player;
    const legs = [[0, 6], [2.0, 0], [2.65, -4], [2.65, -9.4], [0, -10.2]];
    const log = [];
    g.input.keys.add('KeyW');
    for (const [lx, lz] of legs) {
      const [tx, tz] = to(lx, lz);
      const t0 = g.time;
      await __until(() => {
        P.yaw = Math.atan2(-(tx - P.pos.x), -(tz - P.pos.z));
        P.pitch = -0.1;
        return Math.hypot(tx - P.pos.x, tz - P.pos.z) < 0.5 || g.time - t0 > 15;
      }, 400000);
      log.push(Math.hypot(tx - P.pos.x, tz - P.pos.z) < 0.5 ? 'ok' : 'STUCK');
    }
    g.input.keys.delete('KeyW');
    return 'walk to the stern: ' + log.join(' ') + ', ' + Math.hypot(P.pos.x - p.x, P.pos.z - p.z).toFixed(2) + ' m from the fishing spot, on a deck ' + P.onDeck + ', y ' + P.pos.y.toFixed(2);
  })()

(() => {
    const g = __rhf.game;
    const W = g.world;
    const p = W.place('wreck');
    __rhf.tp('wreck');
    const P = g.player;
    P.pitch = -0.2;
    const w = p.wreckAt;
    const c = Math.cos(w.yaw);
    const sn = Math.sin(w.yaw);
    const inHull = (x, z) => {
      const dx = x - w.x;
      const dz = z - w.z;
      const lx = dx * c - dz * sn;
      const lz = dx * sn + dz * c;
      return lz > -12.5 && lz < 14.5 && Math.abs(lx) < 3.8;
    };
    let deep = 0;
    let hull = 0;
    let n = 0;
    for (let i = 0; i < 60; i++) {
      const h = g.fishing.spawnHotspot(p);
      if (!h) continue;
      n++;
      const wa = W.waterAt(h.x, h.z);
      if (wa && wa.depth >= 0.9) deep++;
      if (inHull(h.x, h.z)) hull++;
    }
    const ahead = W.waterAt(P.pos.x - Math.sin(P.yaw) * 25, P.pos.z - Math.cos(P.yaw) * 25);
    return 'wreck stand: on deck ' + P.onDeck + ', y ' + P.pos.y.toFixed(2) + ' (stand ' + p.y.toFixed(2) + '), water 25 m ahead ' + (ahead ? ahead.depth.toFixed(1) + ' m deep' : 'none') + ', hotspots ' + n + '/60 found, ' + deep + ' deep, ' + hull + ' inside the hull';
  })()

(() => {
    const g = __rhf.game;
    const a = g.fishing.aim;
    return 'cast aim from the stern: water ' + a.hasWater + ', primary ' + document.getElementById('btn-primary').textContent;
  })()
